CREATE OR REPLACE VIEW `v_calcolo_enasarco_annuo` AS with `FatturatoAgente` as (select `invoices`.`fornitori_id` AS `fornitori_id`,year(`invoices`.`invoice_date`) AS `anno_competenza`,sum(`invoices`.`total_amount`) AS `totale_fatturato` from `invoices` where (`invoices`.`fornitori_id` is not null) group by `invoices`.`fornitori_id`,year(`invoices`.`invoice_date`)), `AgentiConRegole` as (select `f`.`id` AS `fornitore_id`,`f`.`name` AS `fornitore_name`,`fa`.`anno_competenza` AS `anno_competenza`,`f`.`enasarco` AS `tipo_enasarco`,`fa`.`totale_fatturato` AS `totale_fatturato`,`e`.`aliquota_soc` AS `aliquota_soc`,`e`.`aliquota_agente` AS `aliquota_agente`,(`e`.`aliquota_soc` + `e`.`aliquota_agente`) AS `aliquota_totale`,`e`.`minimale` AS `contributo_minimale`,`e`.`massimale` AS `contributo_massimale`,`e`.`massimo` AS `imponibile_massimale` from ((`FatturatoAgente` `fa` join `fornitoris` `f` on((`fa`.`fornitori_id` = `f`.`id`))) join `enasarcos` `e` on(((`f`.`enasarco` = `e`.`enasarco`) and (`fa`.`anno_competenza` = `e`.`competenza`)))) where ((`f`.`enasarco` <> 'no') and (`f`.`enasarco` is not null) and (`fa`.`totale_fatturato` > 0))), `CalcoloLordo` as (select `AgentiConRegole`.`fornitore_id` AS `fornitore_id`,`AgentiConRegole`.`fornitore_name` AS `fornitore_name`,`AgentiConRegole`.`anno_competenza` AS `anno_competenza`,`AgentiConRegole`.`tipo_enasarco` AS `tipo_enasarco`,`AgentiConRegole`.`totale_fatturato` AS `totale_fatturato`,`AgentiConRegole`.`aliquota_soc` AS `aliquota_soc`,`AgentiConRegole`.`aliquota_agente` AS `aliquota_agente`,`AgentiConRegole`.`aliquota_totale` AS `aliquota_totale`,`AgentiConRegole`.`contributo_minimale` AS `contributo_minimale`,`AgentiConRegole`.`contributo_massimale` AS `contributo_massimale`,`AgentiConRegole`.`imponibile_massimale` AS `imponibile_massimale`,least(`AgentiConRegole`.`totale_fatturato`,`AgentiConRegole`.`imponibile_massimale`) AS `imponibile_contributivo` from `AgentiConRegole`), `CalcoloNetto` as (select `CalcoloLordo`.`fornitore_id` AS `fornitore_id`,`CalcoloLordo`.`fornitore_name` AS `fornitore_name`,`CalcoloLordo`.`anno_competenza` AS `anno_competenza`,`CalcoloLordo`.`tipo_enasarco` AS `tipo_enasarco`,`CalcoloLordo`.`totale_fatturato` AS `totale_fatturato`,`CalcoloLordo`.`aliquota_soc` AS `aliquota_soc`,`CalcoloLordo`.`aliquota_agente` AS `aliquota_agente`,`CalcoloLordo`.`aliquota_totale` AS `aliquota_totale`,`CalcoloLordo`.`contributo_minimale` AS `contributo_minimale`,`CalcoloLordo`.`contributo_massimale` AS `contributo_massimale`,`CalcoloLordo`.`imponibile_massimale` AS `imponibile_massimale`,`CalcoloLordo`.`imponibile_contributivo` AS `imponibile_contributivo`,((`CalcoloLordo`.`imponibile_contributivo` * `CalcoloLordo`.`aliquota_totale`) / 100) AS `contributo_lordo_calcolato`,greatest(`CalcoloLordo`.`contributo_minimale`,least(((`CalcoloLordo`.`imponibile_contributivo` * `CalcoloLordo`.`aliquota_totale`) / 100),`CalcoloLordo`.`contributo_massimale`)) AS `contributo_totale_dovuto` from `CalcoloLordo`) select `CalcoloNetto`.`fornitore_id` AS `fornitore_id`,`CalcoloNetto`.`fornitore_name` AS `fornitore_name`,`CalcoloNetto`.`anno_competenza` AS `anno_competenza`,`CalcoloNetto`.`tipo_enasarco` AS `tipo_enasarco`,`CalcoloNetto`.`totale_fatturato` AS `totale_fatturato`,`CalcoloNetto`.`imponibile_contributivo` AS `imponibile_contributivo`,`CalcoloNetto`.`contributo_totale_dovuto` AS `contributo_totale_dovuto`,(`CalcoloNetto`.`contributo_totale_dovuto` * (`CalcoloNetto`.`aliquota_soc` / `CalcoloNetto`.`aliquota_totale`)) AS `quota_azienda`,(`CalcoloNetto`.`contributo_totale_dovuto` * (`CalcoloNetto`.`aliquota_agente` / `CalcoloNetto`.`aliquota_totale`)) AS `quota_agente`,`CalcoloNetto`.`contributo_lordo_calcolato` AS `contributo_lordo_calcolato`,`CalcoloNetto`.`contributo_minimale` AS `contributo_minimale`,`CalcoloNetto`.`contributo_massimale` AS `contributo_massimale`,`CalcoloNetto`.`imponibile_massimale` AS `imponibile_massimale`,`CalcoloNetto`.`aliquota_soc` AS `aliquota_soc`,`CalcoloNetto`.`aliquota_agente` AS `aliquota_agente` from `CalcoloNetto`
